description:
Implement a combobox state hook. It manages open/close state, an input value for filtering, a filtered options list, and a selected value. `select(option)` sets `selectedValue` and closes the dropdown.

**Example:**
```tsx
const { isOpen, open, close, inputValue, setInputValue, filtered, select, selectedValue } =
  useCombobox(['Apple', 'Banana', 'Cherry']);
```

starter_code:
import { useState, useMemo } from 'react';

export function useCombobox(options: string[]) {
  // your code here
}

test_suite:
test('starts closed with empty input and no selection', () => {
  const { result } = renderHook(() => useCombobox(['A', 'B']));
  expect(result.current.isOpen).toBe(false);
  expect(result.current.inputValue).toBe('');
  expect(result.current.selectedValue).toBeNull();
});

test('open() and close() toggle isOpen', () => {
  const { result } = renderHook(() => useCombobox(['A']));
  act(() => result.current.open());
  expect(result.current.isOpen).toBe(true);
  act(() => result.current.close());
  expect(result.current.isOpen).toBe(false);
});

test('setInputValue filters options case-insensitively', () => {
  const { result } = renderHook(() => useCombobox(['Apple', 'Banana', 'Apricot']));
  act(() => result.current.setInputValue('ap'));
  expect(result.current.filtered).toEqual(['Apple', 'Apricot']);
});

test('select sets selectedValue and closes dropdown', () => {
  const { result } = renderHook(() => useCombobox(['Apple', 'Banana']));
  act(() => result.current.open());
  act(() => result.current.select('Apple'));
  expect(result.current.selectedValue).toBe('Apple');
  expect(result.current.isOpen).toBe(false);
});

test('filtered returns all options when input is empty', () => {
  const { result } = renderHook(() => useCombobox(['X', 'Y', 'Z']));
  expect(result.current.filtered).toEqual(['X', 'Y', 'Z']);
});

// __hidden__
test('close clears inputValue', () => {
  const { result } = renderHook(() => useCombobox(['Apple']));
  act(() => result.current.setInputValue('ap'));
  act(() => result.current.close());
  expect(result.current.inputValue).toBe('');
});

solution:
import { useState, useMemo } from 'react';

export function useCombobox(options: string[]) {
  const [isOpen, setIsOpen] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [selectedValue, setSelectedValue] = useState<string | null>(null);

  const filtered = useMemo(
    () => options.filter(o => o.toLowerCase().includes(inputValue.toLowerCase())),
    [options, inputValue]
  );

  const open = () => setIsOpen(true);
  const close = () => { setIsOpen(false); setInputValue(''); };
  const select = (option: string) => { setSelectedValue(option); setIsOpen(false); };

  return { isOpen, open, close, inputValue, setInputValue, filtered, select, selectedValue };
}
